import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_W 32
#define TILE_H 32
#define THREAD_TILE 2
#define OC_TILE 4
#define OUT_TILE_W (TILE_W * THREAD_TILE)
#define OUT_TILE_H (TILE_H * THREAD_TILE)
__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int kh, int kw,
    int stride,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int tile_h_in, int tile_w_in)
{
    extern __shared__ float shared_mem[];
    int tile_elems = tile_h_in * tile_w_in;
    int kernel_elems = kh * kw;
    int weight_elems = kernel_elems * OC_TILE;
    size_t buf_stride = (size_t)tile_elems + (size_t)weight_elems;
    float* s_input_buf[2];
    float* s_weight_buf[2];
    s_input_buf[0] = shared_mem;
    s_weight_buf[0] = shared_mem + tile_elems;
    s_input_buf[1] = shared_mem + buf_stride;
    s_weight_buf[1] = s_input_buf[1] + tile_elems;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int oc_groups = out_channels / OC_TILE;
    int bc = blockIdx.z;
    int b = bc / oc_groups;
    int oc_group = bc % oc_groups;
    int oc_base = oc_group * OC_TILE;
    int ow0 = blockIdx.x * OUT_TILE_W + tx;
    int oh0 = blockIdx.y * OUT_TILE_H + ty;
    int in_row_base = blockIdx.y * OUT_TILE_H * stride - pad_h;
    int in_col_base = blockIdx.x * OUT_TILE_W * stride - pad_w;
    const float* input_b = input + (size_t)b * in_channels * in_h * in_w;
    const float* weight_oc[OC_TILE];
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
        weight_oc[t] = weight + (size_t)(oc_base + t) * in_channels * kh * kw;
    }
    float sum[OC_TILE][THREAD_TILE][THREAD_TILE];
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
        #pragma unroll
        for (int ti = 0; ti < THREAD_TILE; ++ti) {
            #pragma unroll
            for (int tj = 0; tj < THREAD_TILE; ++tj) {
                sum[t][ti][tj] = 0.0f;
            }
        }
    }
    int tid = ty * TILE_W + tx;
    int num_threads = TILE_W * TILE_H;
    // Prefetch the first input channel's tile and weight slice into buffer 0.
    {
        const float* input_c = input_b;
        float* s_input0 = s_input_buf[0];
        float* s_weight0 = s_weight_buf[0];
        for (int idx = tid; idx < tile_elems; idx += num_threads) {
            int r = idx / tile_w_in;
            int c = idx % tile_w_in;
            int in_row = in_row_base + r;
            int in_col = in_col_base + c;
            float val = 0.0f;
            if (in_row >= 0 && in_row < in_h && in_col >= 0 && in_col < in_w) {
                val = input_c[(size_t)in_row * in_w + in_col];
            }
            s_input0[idx] = val;
        }
        for (int idx = tid; idx < weight_elems; idx += num_threads) {
            int t = idx / kernel_elems;
            int k = idx % kernel_elems;
            s_weight0[idx] = weight_oc[t][k];
        }
    }
    __syncthreads();
    for (int ic = 0; ic < in_channels; ++ic) {
        int cur = ic & 1;
        int nxt = cur ^ 1;
        // Prefetch the next channel's tile/weight into the other buffer while
        // the current buffer is being consumed below, overlapping global
        // memory latency of the next iteration with current compute.
        if (ic + 1 < in_channels) {
            const float* input_c = input_b + (size_t)(ic + 1) * in_h * in_w;
            float* s_input_n = s_input_buf[nxt];
            float* s_weight_n = s_weight_buf[nxt];
            for (int idx = tid; idx < tile_elems; idx += num_threads) {
                int r = idx / tile_w_in;
                int c = idx % tile_w_in;
                int in_row = in_row_base + r;
                int in_col = in_col_base + c;
                float val = 0.0f;
                if (in_row >= 0 && in_row < in_h && in_col >= 0 && in_col < in_w) {
                    val = input_c[(size_t)in_row * in_w + in_col];
                }
                s_input_n[idx] = val;
            }
            for (int idx = tid; idx < weight_elems; idx += num_threads) {
                int t = idx / kernel_elems;
                int k = idx % kernel_elems;
                s_weight_n[idx] = weight_oc[t][(ic + 1) * kernel_elems + k];
            }
        }
        float* s_input = s_input_buf[cur];
        float* s_weight = s_weight_buf[cur];
        #pragma unroll
        for (int i = 0; i < kh; ++i) {
            #pragma unroll
            for (int j = 0; j < kw; ++j) {
                float wv[OC_TILE];
                #pragma unroll
                for (int t = 0; t < OC_TILE; ++t) {
                    wv[t] = s_weight[t * kernel_elems + i * kw + j];
                }
                #pragma unroll
                for (int ti = 0; ti < THREAD_TILE; ++ti) {
                    int sr = (ty + ti * TILE_H) * stride + i * dil_h;
                    const float* s_input_row = s_input + (size_t)sr * tile_w_in;
                    #pragma unroll
                    for (int tj = 0; tj < THREAD_TILE; ++tj) {
                        int sc = (tx + tj * TILE_W) * stride + j * dil_w;
                        float in_val = s_input_row[sc];
                        #pragma unroll
                        for (int t = 0; t < OC_TILE; ++t) {
                            sum[t][ti][tj] += in_val * wv[t];
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int t = 0; t < OC_TILE; ++t) {
        int oc = oc_base + t;
        #pragma unroll
        for (int ti = 0; ti < THREAD_TILE; ++ti) {
            int oh = oh0 + ti * TILE_H;
            if (oh >= out_h) continue;
            #pragma unroll
            for (int tj = 0; tj < THREAD_TILE; ++tj) {
                int ow = ow0 + tj * TILE_W;
                if (ow >= out_w) continue;
                size_t out_idx = ((size_t)b * out_channels + oc) * out_h * out_w + (size_t)oh * out_w + ow;
                output[out_idx] = sum[t][ti][tj];
            }
        }
    }
}
torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int pad_h, int pad_w,
    int dil_h, int dil_w)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);
    int out_channels = weight.size(0);
    int kh = weight.size(2);
    int kw = weight.size(3);
    int out_h = (in_h + 2 * pad_h - dil_h * (kh - 1) - 1) / stride + 1;
    int out_w = (in_w + 2 * pad_w - dil_w * (kw - 1) - 1) / stride + 1;
    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());
    int tile_h_in = (OUT_TILE_H - 1) * stride + (kh - 1) * dil_h + 1;
    int tile_w_in = (OUT_TILE_W - 1) * stride + (kw - 1) * dil_w + 1;
    size_t shared_bytes = 2 * (size_t)(tile_h_in * tile_w_in + (size_t)kh * kw * OC_TILE) * sizeof(float);
    cudaFuncSetAttribute(conv2d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_bytes);
    dim3 block(TILE_W, TILE_H, 1);
    int oc_groups = out_channels / OC_TILE;
    dim3 grid(
        (out_w + OUT_TILE_W - 1) / OUT_TILE_W,
        (out_h + OUT_TILE_H - 1) / OUT_TILE_H,
        batch_size * oc_groups
    );
    conv2d_kernel<<<grid, block, shared_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_h, in_w,
        out_h, out_w,
        kh, kw,
        stride,
        pad_h, pad_w,
        dil_h, dil_w,
        tile_h_in, tile_w_in
    );
    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int pad_h, int pad_w,
    int dil_h, int dil_w);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1,
                 padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size[0], kernel_size[1]))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

        self.conv2d_cuda = conv2d_module.conv2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        out = self.conv2d_cuda(
            x, weight,
            self.stride,
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1]
        )

        if self.has_bias:
            out = out + self.bias.view(1, -1, 1, 1)

        return out


